function FaqItem({ item, isOpen, onToggle }) {
  return (
    <div style={{
      background: '#F3F4F6',
      borderRadius: '8px',
      marginBottom: '12px',
      overflow: 'hidden',
      border: '1px solid #E5E7EB',
    }}>
      <button
        onClick={onToggle}
        style={{
          width: '100%',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          padding: '18px 24px',
          background: 'transparent',
          border: 'none',
          cursor: 'pointer',
          textAlign: 'left',
        }}
      >
        <span style={{
          fontSize: '14px',
          fontWeight: '800',
          letterSpacing: '0.03em',
          color: isOpen ? '#ff0000' : '#374151',
          textTransform: 'uppercase',
        }}>{item.q}</span>
        <span style={{
          flexShrink: 0,
          marginLeft: '16px',
          width: '28px',
          height: '28px',
          borderRadius: '50%',
          background: '#ff0000',
          color: 'white',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          fontSize: '18px',
          fontWeight: '700',
          transform: isOpen ? 'rotate(45deg)' : 'rotate(0deg)',
          transition: 'transform 0.2s',
        }}>+</span>
      </button>
      {isOpen && (
        <div style={{ padding: '0 24px 20px' }}>
          <p style={{ margin: 0, fontSize: '15px', lineHeight: 1.7, color: '#4B5563' }}>{item.a}</p>
        </div>
      )}
    </div>
  );
}

